import{_ as s,o as e,c as a,aj as t}from"./chunks/framework.DpVzuYkC.js";const p=JSON.parse('{"title":"linklist","description":"","frontmatter":{},"headers":[],"relativePath":"linklist/index.md","filePath":"linklist/README.md"}'),l={name:"linklist/index.md"};function n(d,i,r,o,h,c){return e(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="linklist" tabindex="-1">linklist <a class="header-anchor" href="#linklist" aria-label="Permalink to “linklist”">​</a></h1><p><a href="https://github.com/jetsung/linklist" target="_blank" rel="noreferrer">Office Web</a> - <a href="https://github.com/jetsung/linklist" target="_blank" rel="noreferrer">Source</a> - <a href="https://ghcr.io/jetsung/linklist" target="_blank" rel="noreferrer">Docker Image</a> - <a href="https://github.com/jetsung/linklist/tree/main/docs" target="_blank" rel="noreferrer">Document</a></p><hr><blockquote><p><a href="https://github.com/jetsung/linklist" target="_blank" rel="noreferrer">linklist</a> 是一个自托管书签管理服务（Rust 重写的 linkding 替代品），单二进制交付，支持 SQLite（默认）/ PostgreSQL / MySQL 三种数据库。</p></blockquote><p><strong>功能概述</strong>：</p><ul><li>书签 CRUD、全文搜索（FTS5）、表达式搜索（<code>tag:rust</code>、<code>is:unread</code> 等）、标签管理</li><li>自动抓取网页元数据（标题/描述）、Archive.today 快照、web archive 查询</li><li>页面快照与资产上传</li><li>批量操作（加/删标签、已读/未读、删除）、归档与隔离视图</li><li>Netscape 格式导入/导出、RSS 订阅源</li><li>多用户：注册（首个用户自动管理员）、会话 + API Token</li><li>共享书签：共享视图 + 可关闭的匿名公开共享（<code>guest_sharing</code>）</li><li>管理端：用户管理、任务队列、全局设置、审计日志</li></ul><h2 id="首次使用" tabindex="-1">首次使用 <a class="header-anchor" href="#首次使用" aria-label="Permalink to “首次使用”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 65532:65532</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 容器以 uid 65532 运行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>打开 <code>http://localhost:9090/login</code> 完成首次初始化/登录。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><p>容器内使用默认端口 <code>9090</code> 与数据目录 <code>/app/data</code>，其余配置通过 <code>LINKLIST_*</code> 环境变量注入（优先级高于 <code>config.toml</code>）：</p><table tabindex="0"><thead><tr><th>环境变量</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>LINKLIST_LISTEN</code></td><td><code>0.0.0.0:9090</code></td><td>监听地址</td></tr><tr><td><code>LINKLIST_DATA_DIR</code></td><td><code>./data</code></td><td>数据目录</td></tr><tr><td><code>LINKLIST_DATABASE_URL</code></td><td>（空）</td><td>数据库连接串，留空使用 SQLite；<code>postgres://</code> / <code>mysql://</code> 前缀自动选择后端</td></tr><tr><td><code>LINKLIST_GUEST_SHARING</code></td><td><code>false</code></td><td>是否允许匿名访客查看公开共享书签</td></tr><tr><td><code>LINKLIST_LOG</code></td><td><code>info</code></td><td>日志级别（RUST_LOG 语法）</td></tr><tr><td><code>LINKLIST_SESSION_TTL_SECS</code></td><td><code>604800</code></td><td>会话有效期（秒）</td></tr><tr><td><code>LINKLIST_TOKEN_TTL_DAYS</code></td><td><code>0</code></td><td>API Token 有效期（天，0 = 永不过期）</td></tr></tbody></table><h2 id="oidc-单点登录-sso" tabindex="-1">OIDC 单点登录（SSO） <a class="header-anchor" href="#oidc-单点登录-sso" aria-label="Permalink to “OIDC 单点登录（SSO）”">​</a></h2><p>LinkList 支持 OIDC（OpenID Connect）单点登录：授权码流程 + PKCE（S256），回调校验通过后按 claim <strong>自动创建账号并登录</strong>。</p><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to “前置条件”">​</a></h3><ul><li>IdP（Keycloak / Authentik / Casdoor / Auth0 / Logto 等）支持授权码流程 + PKCE；</li><li>在 IdP 注册客户端，重定向 URI 填 <code>http(s)://&lt;服务地址&gt;/oidc/callback/</code>（<strong>带尾部斜杠</strong>；不一致时可用 <code>LINKLIST_OIDC_REDIRECT_URI</code> 显式指定）。</li></ul><h3 id="配置-compose-yaml-的-environment" tabindex="-1">配置（compose.yaml 的 environment） <a class="header-anchor" href="#配置-compose-yaml-的-environment" aria-label="Permalink to “配置（compose.yaml 的 environment）”">​</a></h3><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  linklist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LINKLIST_ENABLE_OIDC=true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LINKLIST_OIDC_ISSUER=https://idp.example.com/realms/master</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LINKLIST_OIDC_CLIENT_ID=linklist</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LINKLIST_OIDC_CLIENT_SECRET=your-client-secret</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 可选：签发算法（默认 RS256，走 JWKS；HS256 的 IdP 设为 HS256）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # - LINKLIST_OIDC_SIGN_ALGO=HS256</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 可选：用户名字段（默认 email；建出随机 ID 用户名时改用 preferred_username）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # - LINKLIST_OIDC_USERNAME_CLAIM=preferred_username</span></span></code></pre></div><ul><li><strong>Issuer 自动发现（推荐）</strong>：配置 <code>LINKLIST_OIDC_ISSUER</code> 后，各端点从 <code>{issuer}/.well-known/openid-configuration</code> 自动获取。</li><li><strong>手动配置端点</strong>：IdP 无发现文档时，逐项配置 <code>LINKLIST_OIDC_AUTHORIZATION_ENDPOINT</code> / <code>LINKLIST_OIDC_TOKEN_ENDPOINT</code> / <code>LINKLIST_OIDC_JWKS_ENDPOINT</code> / <code>LINKLIST_OIDC_USER_ENDPOINT</code>（显式端点优先）。</li></ul><p>重启后打开登录页即出现「OIDC 登录」按钮。纯 SSO 部署可再加 <code>LINKLIST_DISABLE_LOGIN_FORM=true</code> 隐藏密码表单。</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h3><ul><li>首个经 OIDC 建号的账号自动成为超级用户（单管理员模型）；其后均为普通用户。</li><li>置于 Nginx/Caddy 反代之后时，需正确转发 <code>Host</code> 与 <code>X-Forwarded-Proto</code>，否则回调地址推导与 IdP 注册值不一致会导致授权失败。</li><li>更多排查项见官方文档 <a href="https://github.com/jetsung/linklist/blob/main/docs/07-oidc.md" target="_blank" rel="noreferrer">OIDC 单点登录</a>。</li></ul>`,22)])])}const I=s(l,[["render",n]]);export{p as __pageData,I as default};
